if __name__ == '__main__':
    import json
    p = '/tmp/rfcms/site/data/ui.json'; ui = json.load(open(p))
    L = ['en', 'lv', 'ru', 'nl', 'de', 'sv']
    for row in P:
        assert len(row) == 7, row[0]
        ui[row[0]] = dict(zip(L, row[1:]))
    json.dump(ui, open(p, 'w'), ensure_ascii=False, indent=1)
    s = json.load(open('/tmp/rfcms/site/data/settings.json'))
    s.setdefault('portal', {'registration': 'auto', 'vat': 21, 'valid_days': 30, 'notify': ''})
    s['portal']['terms'] = TERMS
    json.dump(s, open('/tmp/rfcms/site/data/settings.json', 'w'), ensure_ascii=False, indent=1)
    print('portal strings:', len(P), 'ui total:', len(ui))
